import './style.css';
import { loadState, saveState, resetState, exportBackup, importBackup } from './store.js';
import { money, parseDate, dateString, today, addDays, nextOccurrence, occurrencesBetween, generatePayPeriods, periodPlan, monthlyActuals, budgetStatus, netWorth, investmentProjection, debtPayoff, upcomingEvents, financialActions, affordabilityPlan, financialSnapshot, vehicleDecision, housingDecision, incomeChangeDecision, overtimeDecision, bonusAllocationDecision, refinanceDecision, whatIfDecision } from './engine.js';
import { estimatePaycheck } from './tax-engine.js';
import { US_STATES, MD_LOCAL_2026, NO_WAGE_INCOME_TAX_STATES, TAX_YEAR, TAX_DATA_VERSION } from './tax-data.js';

let state=loadState();
const app=document.querySelector('#app');
const uid=()=>crypto.randomUUID?.()||`${Date.now()}-${Math.random()}`;
const esc=(s='')=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const cur=()=>state.profile.currency||'USD';
const route=()=>((location.hash||'#/dashboard').slice(2).split('/')[0]||'dashboard');
const primaryIncome=()=>state.income.find(x=>x.isPrimaryPaycheck===true)||state.income.find(x=>x.name==='Primary paycheck')||null;
const freqOpts=[['weekly','Weekly'],['biweekly','Every 2 weeks'],['semimonthly','Twice monthly'],['monthly','Monthly'],['quarterly','Quarterly'],['annual','Annually']];
const accountTypes=['Checking','Savings','Cash','Credit Union','Money Market','Property','Vehicle','Other Asset'];
const categories=['Housing','Utilities','Groceries','Dining','Transportation','Insurance','Healthcare','Debt','Entertainment','Shopping','Education','Family','Giving','Travel','Subscriptions','Personal','Taxes','Other'];

const navGroups=[
  ['HOME',[['dashboard','Dashboard','▦'],['action-center','Action Center','✓'],['decision-center','Decision Center','◆'],['calendar','Calendar','□']]],
  ['PLAN',[['paycheck-tax','Paycheck & Taxes','$'],['pay-periods','Pay Periods','◫'],['budget','Monthly Budget','◩'],['income','Income','＋'],['bills','Bills & Subscriptions','▤'],['affordability','Affordability Planner','⌂']]],
  ['TRACK',[['accounts','Accounts','○'],['transactions','Transactions','⇄'],['net-worth','Net Worth','◇']]],
  ['GROW',[['debts','Debt Payoff','↓'],['goals','Goals & Sinking Funds','◎'],['investments','Investments','↗']]],
  ['REVIEW',[['reports','Reports','▥'],['guide','Money Guide','?'],['settings','Settings & Backup','⚙']]]
];

function persist(msg='Saved'){state=saveState(state);toast(msg);}
function layout(content){
  const r=route();
  app.innerHTML=`<div class="shell">
    <aside class="sidebar"><a class="brand" href="#/dashboard"><span class="logo">OB</span><span><strong>OwnLedger</strong><small>Private. Offline. Yours.</small></span></a>
    <nav>${navGroups.map(([g,items])=>`<div class="navGroup"><span class="navLabel">${g}</span>${items.map(([id,label,icon])=>`<a class="${r===id?'active':''}" href="#/${id}"><span>${icon}</span>${label}</a>`).join('')}</div>`).join('')}</nav>
    <div class="offline"><b>● Offline mode</b><span>Network access is disabled in the desktop app.</span></div></aside>
    <main><header class="topbar"><button id="menuBtn" class="iconBtn" aria-label="Toggle navigation">☰</button><div class="privacyTop">Your financial data stays on this device</div><button class="button ghost small" id="quickTx">+ Transaction</button></header><div class="page">${content}</div></main>
  </div><dialog id="modal"><form id="modalForm"><div id="modalBody"></div></form></dialog><div id="toast" role="status" aria-live="polite"></div>`;
  document.querySelector('#menuBtn').onclick=()=>document.querySelector('.sidebar').classList.toggle('open');
  document.querySelector('#quickTx').onclick=()=>openTransaction();
}
const title=(k,h,p='',a='')=>`<section class="pageTitle"><div><span class="kicker">${esc(k)}</span><h1>${esc(h)}</h1>${p?`<p>${esc(p)}</p>`:''}</div><div class="actions">${a}</div></section>`;
const button=(label,id,cls='primary')=>`<button type="button" class="button ${cls}" id="${id}">${esc(label)}</button>`;
const stat=(l,v,s='')=>`<article class="stat"><span>${esc(l)}</span><strong>${v}</strong>${s?`<small>${esc(s)}</small>`:''}</article>`;
const empty=(h,p,b='')=>`<div class="empty"><div class="emptyIcon">◇</div><h3>${esc(h)}</h3><p>${esc(p)}</p>${b}</div>`;
function toast(msg){const t=document.querySelector('#toast');if(!t)return;t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200);}
function openModal(html,onSubmit){const d=document.querySelector('#modal'),f=document.querySelector('#modalForm');document.querySelector('#modalBody').innerHTML=html;f.onsubmit=e=>{e.preventDefault();onSubmit(new FormData(f));d.close();render();};document.querySelectorAll('[data-close]').forEach(x=>x.onclick=()=>d.close());d.showModal();}
const modalHeader=(h,p='')=>`<div class="modalHead"><div><h2>${esc(h)}</h2>${p?`<p>${esc(p)}</p>`:''}</div><button type="button" class="iconBtn" data-close>×</button></div>`;
const field=(l,n,t='text',v='',attrs='')=>`<label class="field"><span>${esc(l)}</span><input name="${n}" type="${t}" value="${esc(v)}" ${attrs}></label>`;
const select=(l,n,v,opts)=>`<label class="field"><span>${esc(l)}</span><select name="${n}">${opts.map(o=>{const [x,y]=Array.isArray(o)?o:[o,o];return`<option value="${esc(x)}" ${x===v?'selected':''}>${esc(y)}</option>`}).join('')}</select></label>`;
const actions=save=>`<div class="modalActions"><button type="button" class="button ghost" data-close>Cancel</button><button class="button primary" type="submit">${esc(save||'Save')}</button></div>`;
const checkbox=(l,n,checked)=>`<label class="check"><input type="checkbox" name="${n}" ${checked?'checked':''}><span>${esc(l)}</span></label>`;

function dashboard(){
  const nw=netWorth(state), actual=monthlyActuals(state), plans=generatePayPeriods(state,2), next=plans[0]?periodPlan(state,plans[0]):null, acts=financialActions(state), ev=upcomingEvents(state,21).slice(0,6), debt=debtPayoff(state);
  layout(`${title('CONTROL CENTER',state.profile.name?`${state.profile.name}'s finances`:'Your finances','A simple view of where you stand, what comes next, and what deserves attention.',!state.settings.onboardingComplete?button('Finish setup','setup'):button('Add transaction','dashTx','ghost'))}
  ${!state.settings.onboardingComplete?`<div class="callout"><div><strong>Start with four simple things</strong><p>Add your next payday, take-home pay, main account balance, and emergency-fund target. Everything else can be added later.</p></div>${button('Set up OwnLedger','setup2')}</div>`:''}
  <section class="stats">${stat('Net worth',money(nw.net,cur()),`${money(nw.assets,cur())} assets − ${money(nw.liabilities,cur())} debt`)}${stat('This month spent',money(actual.expenses,cur()),`${money(actual.income,cur())} recorded income`)}${stat('Next paycheck free',next?money(next.available,cur()):'—','After scheduled bills, goals & investing')}${stat('Debt-free estimate',state.debts.length?(debt.complete?debt.debtFree:'Not achievable'):'—',state.debts.length?(debt.complete?`${debt.months} months at current plan`:'Increase the current debt payment'):'Add debt to calculate')}</section>
  <section class="grid2"><article class="card"><div class="cardHead"><div><span class="kicker">WHAT TO DO NEXT</span><h2>Action center</h2></div><a href="#/action-center">See all →</a></div>${acts.length?acts.slice(0,4).map(a=>`<a class="actionItem ${a.level}" href="#/${a.route}"><span class="actionMark">${a.level==='high'?'!':'→'}</span><div><b>${esc(a.title)}</b><small>${esc(a.text)}</small></div></a>`).join(''):`<div class="goodState"><b>You are caught up.</b><span>No urgent financial setup or planning issues were found.</span></div>`}</article>
  <article class="card"><div class="cardHead"><div><span class="kicker">NEXT 21 DAYS</span><h2>Money calendar</h2></div><a href="#/calendar">Open calendar →</a></div>${ev.length?`<div class="list">${ev.map(x=>`<div class="row"><div><b>${esc(x.name)}</b><small>${x.date} · ${esc(x.type)}</small></div><strong class="${x.type==='income'?'positive':''}">${x.type==='income'?'+':'−'}${money(x.amount,cur())}</strong></div>`).join('')}</div>`:empty('Nothing scheduled','Add recurring income or bills and OwnLedger will build the calendar automatically.')}</article></section>
  <section class="grid2"><article class="card"><div class="cardHead"><div><span class="kicker">NEXT PAYCHECK</span><h2>${plans[0]?dateString(plans[0].payDate):'Not configured'}</h2></div><a href="#/pay-periods">Full plan →</a></div>${next?`<div class="moneyFlow"><div><span>Take-home income</span><b>${money(next.income,cur())}</b></div><div><span>Bills & subscriptions</span><b>− ${money(next.bills,cur())}</b></div><div><span>Investing</span><b>− ${money(next.investments,cur())}</b></div><div><span>Savings goals</span><b>− ${money(next.goals,cur())}</b></div><div><span>Debt minimum reserve</span><b>− ${money(next.debtPayments||0,cur())}</b></div><div class="total"><span>Left to spend / assign</span><b class="${next.available<0?'negative':''}">${money(next.available,cur())}</b></div></div>`:empty('Paycheck planning is off','Add your next payday and recurring income to generate plans.')}</article>
  <article class="card"><div class="cardHead"><div><span class="kicker">FINANCIAL POSITION</span><h2>Where your money sits</h2></div><a href="#/net-worth">Net worth →</a></div><div class="position"><div><span>Cash & assets</span><b>${money(nw.assets,cur())}</b><i style="width:${nw.assets+nw.liabilities?Math.max(2,nw.assets/(nw.assets+nw.liabilities)*100):0}%"></i></div><div><span>Debt</span><b>${money(nw.liabilities,cur())}</b><i class="debtBar" style="width:${nw.assets+nw.liabilities?Math.max(2,nw.liabilities/(nw.assets+nw.liabilities)*100):0}%"></i></div></div></article></section>`);
  document.querySelector('#setup')?.addEventListener('click',openSetup);document.querySelector('#setup2')?.addEventListener('click',openSetup);document.querySelector('#dashTx')?.addEventListener('click',openTransaction);
}

function openSetup(){
  const primary=primaryIncome();const checking=state.accounts.find(a=>a.type==='Checking');
  openModal(`${modalHeader('Simple setup','You can change every value later. Nothing leaves this device.')}<div class="formGrid">${field('Your name (optional)','name','text',state.profile.name)}${select('Pay frequency','payFrequency',state.profile.payFrequency,[['weekly','Weekly'],['biweekly','Every 2 weeks'],['semimonthly','Twice monthly'],['monthly','Monthly']])}${field('Next payday','nextPayDate','date',state.profile.nextPayDate,'required')}${field('Take-home pay each payday','payAmount','number',primary?.amount||'','min="0" step="0.01" required')}${field('Checking balance','checking','number',checking?.balance||0,'step="0.01"')}${field('Emergency fund target','emergency','number',state.profile.emergencyFundTarget,'min="0" step="0.01"')}</div>${actions('Finish setup')}`,fd=>{
    state.profile.name=fd.get('name');state.profile.payFrequency=fd.get('payFrequency');state.profile.nextPayDate=fd.get('nextPayDate');state.profile.emergencyFundTarget=Number(fd.get('emergency'));
    const pf=state.profile.payFrequency==='semimonthly'?'semimonthly':state.profile.payFrequency;
    if(primary){primary.amount=Number(fd.get('payAmount'));primary.frequency=pf;primary.startDate=state.profile.nextPayDate;primary.isPrimaryPaycheck=true;}else state.income.push({id:uid(),name:'Primary paycheck',amount:Number(fd.get('payAmount')),frequency:pf,startDate:state.profile.nextPayDate,category:'Paycheck',active:true,isPrimaryPaycheck:true});
    if(checking)checking.balance=Number(fd.get('checking'));else state.accounts.push({id:uid(),name:'Checking',type:'Checking',balance:Number(fd.get('checking')),includeNetWorth:true});
    state.settings.onboardingComplete=true;persist('Setup complete');
  });
}

function actionCenter(){const a=financialActions(state);layout(`${title('GUIDANCE','Action Center','OwnLedger turns your own information into simple next steps. It never sends your data anywhere.')}<article class="card">${a.length?a.map(x=>`<a class="actionItem ${x.level}" href="#/${x.route}"><span class="actionMark">${x.level==='high'?'!':'→'}</span><div><b>${esc(x.title)}</b><small>${esc(x.text)}</small></div><span class="priority">${x.level}</span></a>`).join(''):`<div class="goodState large"><b>No urgent actions found</b><span>Keep recording actual transactions and update balances periodically so the guidance stays useful.</span></div>`}</article><article class="card"><span class="kicker">HOW TO USE THIS</span><h2>Four habits are enough</h2><div class="steps"><div><b>1. Plan each paycheck</b><span>Know what must be covered before you spend.</span></div><div><b>2. Record actual spending</b><span>Manual entry or offline CSV import is enough.</span></div><div><b>3. Update balances monthly</b><span>Accounts, debts, and investments drive net worth.</span></div><div><b>4. Make a backup</b><span>Your device is the only copy unless you export one.</span></div></div></article>`);}

function payPeriods(){const periods=generatePayPeriods(state,18);layout(`${title('PAYCHECK PLANNING','Pay Periods','See exactly what every upcoming paycheck needs to cover before discretionary spending.',button('Edit payday','editPay'))}${periods.length?`<div class="periods">${periods.map((p,i)=>{const x=periodPlan(state,p),committed=x.bills+x.investments+x.goals+(x.debtPayments||0),pct=x.income?Math.min(100,committed/x.income*100):0;return`<article class="periodCard"><div class="periodHead"><div><span class="pill">${i===0?'NEXT PAYCHECK':'PAY PERIOD'}</span><h2>${dateString(p.payDate)}</h2><small>${dateString(p.start)} — ${dateString(p.end)}</small></div><strong class="${x.available<0?'negative':''}">${money(x.available,cur())}<small>left after commitments</small></strong></div><div class="allocation"><i style="width:${pct}%"></i></div><div class="periodNumbers"><span>Income<b>${money(x.income,cur())}</b></span><span>Bills<b>${money(x.bills,cur())}</b></span><span>Invest<b>${money(x.investments,cur())}</b></span><span>Goals<b>${money(x.goals,cur())}</b></span><span>Debt reserve<b>${money(x.debtPayments||0,cur())}</b></span></div><details><summary>Show what is scheduled</summary><div class="detailsGrid"><div><h4>Income</h4>${x.incomeItems.map(i=>`<p>${esc(i.name)}<b>${money(i.value,cur())}</b></p>`).join('')||'<p>None</p>'}</div><div><h4>Bills</h4>${x.billItems.map(i=>`<p>${esc(i.name)}<b>${money(i.value,cur())}</b></p>`).join('')||'<p>None</p>'}</div><div><h4>Goals & investing</h4>${[...x.investmentItems,...x.goalItems].map(i=>`<p>${esc(i.name)}<b>${money(i.value,cur())}</b></p>`).join('')||'<p>None</p>'}</div></div></details></article>`}).join('')}</div>`:empty('Set your payday first','Future pay periods will then generate automatically.',button('Set payday','editPay2'))}`);document.querySelector('#editPay')?.addEventListener('click',editPay);document.querySelector('#editPay2')?.addEventListener('click',editPay);}
function editPay(){openModal(`${modalHeader('Pay schedule')}<div class="formGrid">${select('Pay frequency','payFrequency',state.profile.payFrequency,[['weekly','Weekly'],['biweekly','Every 2 weeks'],['semimonthly','Twice monthly'],['monthly','Monthly']])}${field('Next payday','nextPayDate','date',state.profile.nextPayDate,'required')}</div>${actions()}`,fd=>{state.profile.payFrequency=fd.get('payFrequency');state.profile.nextPayDate=fd.get('nextPayDate');persist('Pay schedule updated');});}

function recurringPage(kind){const isIncome=kind==='income',arr=isIncome?state.income:state.bills;layout(`${title(isIncome?'MONEY IN':'MONEY OUT',isIncome?'Income':'Bills & Subscriptions',isIncome?'Add paychecks, benefits, pension, side income, or other recurring money.':'Add recurring obligations once. They will automatically land in the correct pay period and calendar.',button(isIncome?'Add income':'Add bill','add'))}<article class="card tableCard">${arr.length?`<div class="table"><div class="tr recurring th"><span>Name</span><span>Amount</span><span>Frequency</span><span>Next date</span><span></span></div>${arr.map(x=>{const n=nextOccurrence(x);return`<div class="tr recurring"><span><b>${esc(x.name)}</b><small>${esc(x.category||'')}</small></span><span>${money(x.amount,cur())}</span><span>${esc(x.frequency)}</span><span>${n?dateString(n):'—'}</span><span class="rowActions"><button data-edit="${x.id}">Edit</button><button data-del="${x.id}">Delete</button></span></div>`}).join('')}</div>`:empty(`No ${isIncome?'income':'bills'} yet`,isIncome?'Add your first recurring income source.':'Add rent, utilities, insurance, subscriptions, or any other regular bill. Debt minimums belong in Debt Payoff and are reserved automatically.',button(isIncome?'Add income':'Add bill','add2'))}</article>${!isIncome?`<article class="card tip"><b>Tip: subscriptions belong here too.</b><span>Use the “Subscriptions” category so Reports can show how much recurring convenience spending costs each month and year.</span></article>`:''}`);const open=item=>openRecurring(kind,item);document.querySelector('#add')?.addEventListener('click',()=>open());document.querySelector('#add2')?.addEventListener('click',()=>open());document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>open(arr.find(x=>x.id===b.dataset.edit)));document.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>{if(confirm('Delete this recurring item?')){arr.splice(arr.findIndex(x=>x.id===b.dataset.del),1);persist('Deleted');render();}});}
function openRecurring(kind,item){const isIncome=kind==='income',arr=isIncome?state.income:state.bills;openModal(`${modalHeader(item?'Edit item':`Add ${kind}`)}<div class="formGrid">${field('Name','name','text',item?.name||'','required')}${field('Amount','amount','number',item?.amount||'','min="0" step="0.01" required')}${select('Category','category',item?.category||(isIncome?'Paycheck':'Housing'),isIncome?['Paycheck','Benefits','Pension','Side income','Other']:categories)}${select('How often?','frequency',item?.frequency||(isIncome?'biweekly':'monthly'),freqOpts)}${field(isIncome?'First payment date':'First due date','startDate','date',item?.startDate||dateString(today()),'required')}${field('End date (optional)','endDate','date',item?.endDate||'')}</div>${actions()}`,fd=>{const d={id:item?.id||uid(),name:fd.get('name'),amount:Number(fd.get('amount')),category:fd.get('category'),frequency:fd.get('frequency'),startDate:fd.get('startDate'),endDate:fd.get('endDate'),active:true};if(item)Object.assign(item,d);else arr.push(d);persist('Recurring item saved');});}

function accounts(){const total=state.accounts.reduce((s,a)=>s+Number(a.balance||0),0);layout(`${title('WHAT YOU OWN','Accounts','Keep a simple snapshot of checking, savings, cash, property, vehicles, and other assets. No bank connection required.',button('Add account','addAccount'))}<section class="stats">${stat('Account balances',money(total,cur()),`${state.accounts.length} account${state.accounts.length===1?'':'s'}`)}${stat('Cash available',money(state.accounts.filter(a=>['Checking','Savings','Cash','Money Market'].includes(a.type)).reduce((s,a)=>s+Number(a.balance||0),0),cur()),'Checking + savings + cash')}</section><section class="cards">${state.accounts.length?state.accounts.map(a=>`<article class="card accountCard"><div class="cardHead"><div><span class="kicker">${esc(a.type)}</span><h2>${esc(a.name)}</h2></div><div class="rowActions"><button data-edit="${a.id}">Edit</button><button data-del="${a.id}">Delete</button></div></div><div class="bigNumber">${money(a.balance,cur())}</div><small class="muted">${a.includeNetWorth!==false?'Included in net worth':'Excluded from net worth'}</small></article>`).join(''):empty('No accounts yet','Add balances manually. Updating them once a month is enough for useful net-worth tracking.',button('Add account','addAccount2'))}</section>`);document.querySelector('#addAccount')?.addEventListener('click',()=>openAccount());document.querySelector('#addAccount2')?.addEventListener('click',()=>openAccount());document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openAccount(state.accounts.find(a=>a.id===b.dataset.edit)));document.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>{if(confirm('Delete account?')){state.accounts=state.accounts.filter(a=>a.id!==b.dataset.del);persist('Account deleted');render();}});}
function openAccount(item){openModal(`${modalHeader(item?'Edit account':'Add account')}<div class="formGrid">${field('Account name','name','text',item?.name||'','required')}${select('Type','type',item?.type||'Checking',accountTypes)}${field('Current balance / value','balance','number',item?.balance||0,'step="0.01" required')}</div><div class="modalChecks">${checkbox('Include this value in net worth','includeNetWorth',item?.includeNetWorth!==false)}</div>${actions()}`,fd=>{const d={id:item?.id||uid(),name:fd.get('name'),type:fd.get('type'),balance:Number(fd.get('balance')),includeNetWorth:fd.has('includeNetWorth')};if(item)Object.assign(item,d);else state.accounts.push(d);persist('Account saved');});}

function budget(){const rows=budgetStatus(state),actual=monthlyActuals(state),allocated=state.budgets.reduce((s,b)=>s+Number(b.monthlyLimit||0),0),spent=rows.reduce((s,b)=>s+b.spent,0);layout(`${title('SPENDING PLAN','Monthly Budget','Set simple category limits. Transactions automatically count against the matching category.',button('Add category','addBudget'))}<section class="stats">${stat('Planned spending',money(allocated,cur()),'Monthly category limits')}${stat('Actual spending',money(spent,cur()),'Recorded this month')}${stat('Remaining',money(allocated-spent,cur()),'Across configured categories')}${stat('Uncategorized',money(actual.transactions.filter(t=>t.type==='expense'&&!t.category).reduce((s,t)=>s+Number(t.amount||0),0),cur()),'Assign categories for better reports')}</section><article class="card">${rows.length?rows.map(b=>`<div class="budgetRow"><div class="budgetTop"><div><b>${esc(b.category)}</b><small>${money(b.spent,cur())} spent of ${money(b.monthlyLimit,cur())}</small></div><div><strong class="${b.remaining<0?'negative':''}">${money(b.remaining,cur())}</strong><div class="rowActions"><button data-edit="${b.id}">Edit</button><button data-del="${b.id}">Delete</button></div></div></div><div class="bar large ${b.pct>100?'over':''}"><i style="width:${Math.min(100,b.pct)}%"></i></div></div>`).join(''):empty('No category budget yet','Start with only the categories you actually want to control, such as dining, groceries, shopping, or entertainment.',button('Add category','addBudget2'))}</article>`);document.querySelector('#addBudget')?.addEventListener('click',()=>openBudget());document.querySelector('#addBudget2')?.addEventListener('click',()=>openBudget());document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openBudget(state.budgets.find(x=>x.id===b.dataset.edit)));document.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>{state.budgets=state.budgets.filter(x=>x.id!==b.dataset.del);persist('Budget category removed');render();});}
function openBudget(item){openModal(`${modalHeader(item?'Edit budget category':'Add budget category')}<div class="formGrid">${select('Category','category',item?.category||'Groceries',categories)}${field('Monthly limit','monthlyLimit','number',item?.monthlyLimit||'','min="0" step="0.01" required')}</div>${actions()}`,fd=>{const existing=state.budgets.find(x=>x.category===fd.get('category')&&x.id!==item?.id);if(existing){existing.monthlyLimit=Number(fd.get('monthlyLimit'));}else{const d={id:item?.id||uid(),category:fd.get('category'),monthlyLimit:Number(fd.get('monthlyLimit'))};if(item)Object.assign(item,d);else state.budgets.push(d);}persist('Budget saved');});}

function transactions(){const tx=[...state.transactions].sort((a,b)=>b.date.localeCompare(a.date)),inc=tx.filter(x=>x.type==='income').reduce((s,x)=>s+Number(x.amount),0),exp=tx.filter(x=>x.type==='expense').reduce((s,x)=>s+Number(x.amount),0);layout(`${title('WHAT ACTUALLY HAPPENED','Transactions','Record income and spending manually or import an offline CSV. Nothing is connected to a bank.',`${button('Import CSV','importCsv','ghost')}${button('Add transaction','addTx')}`)}<section class="stats">${stat('Recorded income',money(inc,cur()))}${stat('Recorded expenses',money(exp,cur()))}${stat('Recorded net',money(inc-exp,cur()))}</section><article class="card tableCard">${tx.length?`<div class="table"><div class="tr tx th"><span>Date</span><span>Description</span><span>Category</span><span>Account</span><span>Amount</span><span></span></div>${tx.map(x=>`<div class="tr tx"><span>${esc(x.date)}</span><span><b>${esc(x.description)}</b><small>${esc(x.type)}</small></span><span>${esc(x.category||'—')}</span><span>${esc(state.accounts.find(a=>a.id===x.accountId)?.name||'—')}</span><span class="${x.type==='income'?'positive':'negative'}">${x.type==='income'?'+':'−'}${money(x.amount,cur())}</span><span class="rowActions"><button data-del="${x.id}">Delete</button></span></div>`).join('')}</div>`:empty('No transactions yet','Add spending and income, or import the included standard CSV format.',button('Add transaction','addTx2'))}</article>`);document.querySelector('#addTx')?.addEventListener('click',openTransaction);document.querySelector('#addTx2')?.addEventListener('click',openTransaction);document.querySelector('#importCsv')?.addEventListener('click',openCsvImport);document.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>{if(confirm('Delete this transaction?')){state.transactions=state.transactions.filter(x=>x.id!==b.dataset.del);persist('Transaction deleted');render();}});}
function openTransaction(){openModal(`${modalHeader('Add transaction','Keep it simple: date, description, amount, and category.')}<div class="formGrid">${select('Type','type','expense',[['expense','Expense'],['income','Income']])}${field('Date','date','date',dateString(today()),'required')}${field('Description','description','text','','required')}${field('Amount','amount','number','','min="0" step="0.01" required')}${select('Category','category','Other',categories)}${select('Account','accountId','',[['','No account selected'],...state.accounts.map(a=>[a.id,a.name])])}</div>${actions('Add transaction')}`,fd=>{state.transactions.push({id:uid(),type:fd.get('type'),date:fd.get('date'),description:fd.get('description'),amount:Number(fd.get('amount')),category:fd.get('category'),accountId:fd.get('accountId')});persist('Transaction added');});}
function parseCSV(text){const lines=text.replace(/\r/g,'').split('\n').filter(Boolean);if(lines.length<2)return[];const split=line=>{let out=[],cur='',q=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'){if(q&&line[i+1]==='"'){cur+='"';i++;}else q=!q;}else if(c===','&&!q){out.push(cur);cur='';}else cur+=c;}out.push(cur);return out;};const h=split(lines[0]).map(x=>x.trim().toLowerCase());return lines.slice(1).map(line=>{const v=split(line),o={};h.forEach((k,i)=>o[k]=v[i]?.trim()||'');return o;});}
function openCsvImport(){openModal(`${modalHeader('Import offline CSV','Required columns: date, description, amount. Optional: type, category. Negative amounts are treated as expenses.')}<div class="fileDrop"><input type="file" name="csv" accept=".csv,text/csv" required><p>Example header:</p><code>date,description,amount,type,category</code></div>${actions('Import CSV')}`,async fd=>{});const form=document.querySelector('#modalForm');form.onsubmit=async e=>{e.preventDefault();const file=new FormData(form).get('csv');try{const rows=parseCSV(await file.text());let count=0;for(const r of rows){if(!r.date||!r.description||r.amount==='')continue;if(!parseDate(r.date))continue;const raw=Number(String(r.amount).replace(/[$,]/g,''));if(Number.isNaN(raw))continue;const explicitType=String(r.type||'').trim().toLowerCase();const type=explicitType==='income'?'income':explicitType==='expense'?'expense':raw<0?'expense':'income';state.transactions.push({id:uid(),date:r.date,description:r.description,amount:Math.abs(raw),type,category:r.category||'Other',accountId:''});count++;}persist(`${count} transactions imported`);document.querySelector('#modal').close();render();}catch(err){alert(`Could not import CSV: ${err.message}`);}};}

function debts(){const payoff=debtPayoff(state),total=state.debts.reduce((s,d)=>s+Number(d.balance||0),0),minimum=state.debts.reduce((s,d)=>s+Number(d.minimum||0),0);layout(`${title('GET OUT OF DEBT','Debt Payoff','Compare avalanche and snowball strategies using your balances, APRs, minimums, and optional extra monthly payment.',button('Add debt','addDebt'))}<section class="stats">${stat('Total debt',money(total,cur()))}${stat('Minimum payments',money(minimum,cur()),'Per month')}${stat('Estimated debt-free',state.debts.length?(payoff.complete?payoff.debtFree:'Not achievable'):'—',state.debts.length?(payoff.complete?`${payoff.months} months`:'Increase the payment to create a payoff path'):'Add debts first')}${stat('Projected interest',state.debts.length?money(payoff.interest,cur()):'—','At current strategy')}</section><article class="card"><div class="strategy"><div>${select('Payoff strategy','strategy',state.settings.debtStrategy,[['avalanche','Avalanche — highest APR first'],['snowball','Snowball — lowest balance first']])}</div><div>${field('Extra payment / month','extra','number',state.settings.extraDebtPayment,'min="0" step="0.01"')}</div><button class="button primary" type="button" id="saveStrategy">Update plan</button></div><p class="muted">Avalanche usually minimizes interest. Snowball can create faster psychological wins. Minimum payments are always applied first.</p></article><section class="cards">${state.debts.length?state.debts.map(d=>`<article class="card"><div class="cardHead"><div><span class="kicker">${esc(d.type||'DEBT')}</span><h2>${esc(d.name)}</h2></div><div class="rowActions"><button data-edit="${d.id}">Edit</button><button data-del="${d.id}">Delete</button></div></div><div class="bigNumber">${money(d.balance,cur())}<small>remaining balance</small></div><div class="miniStats"><span>APR<b>${Number(d.apr||0).toFixed(2)}%</b></span><span>Minimum<b>${money(d.minimum,cur())}</b></span><span>Priority score<b>${state.settings.debtStrategy==='avalanche'?`${Number(d.apr||0).toFixed(1)}% APR`:money(d.balance,cur())}</b></span></div></article>`).join(''):empty('No debts entered','Add credit cards, loans, lines of credit, or other balances you want to eliminate.',button('Add debt','addDebt2'))}</section>`);document.querySelector('#addDebt')?.addEventListener('click',()=>openDebt());document.querySelector('#addDebt2')?.addEventListener('click',()=>openDebt());document.querySelector('#saveStrategy').onclick=()=>{state.settings.debtStrategy=document.querySelector('[name=strategy]').value;state.settings.extraDebtPayment=Number(document.querySelector('[name=extra]').value);persist('Debt plan updated');render();};document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openDebt(state.debts.find(d=>d.id===b.dataset.edit)));document.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>{if(confirm('Delete debt?')){state.debts=state.debts.filter(d=>d.id!==b.dataset.del);persist('Debt deleted');render();}});}
function openDebt(item){openModal(`${modalHeader(item?'Edit debt':'Add debt')}<div class="formGrid">${field('Debt name','name','text',item?.name||'','required')}${select('Type','type',item?.type||'Credit Card',['Credit Card','Personal Loan','Auto Loan','Student Loan','Mortgage','Medical','Line of Credit','Other'])}${field('Current balance','balance','number',item?.balance||'','min="0" step="0.01" required')}${field('APR %','apr','number',item?.apr||0,'min="0" step="0.01" required')}${field('Minimum monthly payment','minimum','number',item?.minimum||0,'min="0" step="0.01" required')}</div>${actions()}`,fd=>{const d={id:item?.id||uid(),name:fd.get('name'),type:fd.get('type'),balance:Number(fd.get('balance')),apr:Number(fd.get('apr')),minimum:Number(fd.get('minimum'))};if(item)Object.assign(item,d);else state.debts.push(d);persist('Debt saved');});}

function goals(){layout(`${title('SAVE ON PURPOSE','Goals & Sinking Funds','Use goals for emergencies, travel, annual expenses, large purchases, or anything you want to fund before it becomes a problem.',button('Add goal','addGoal'))}<section class="cards">${state.goals.length?state.goals.map(g=>{const pct=Math.min(100,Number(g.saved||0)/Math.max(1,Number(g.target||0))*100);return`<article class="card"><div class="cardHead"><div><span class="kicker">${esc(g.kind||'GOAL')}</span><h2>${esc(g.name)}</h2></div><div class="rowActions"><button data-edit="${g.id}">Edit</button><button data-del="${g.id}">Delete</button></div></div><div class="goalBig"><strong>${money(g.saved,cur())}</strong><span>of ${money(g.target,cur())}</span></div><div class="bar large"><i style="width:${pct}%"></i></div><div class="goalFoot"><span>${Math.round(pct)}% complete</span><span>${money(g.autoContribution||0,cur())} / paycheck</span></div>${g.deadline?`<small class="muted">Target date: ${esc(g.deadline)}</small>`:''}</article>`}).join(''):empty('No savings goals yet','A sinking fund turns future expenses into smaller predictable contributions.',button('Add goal','addGoal2'))}</section>`);document.querySelector('#addGoal')?.addEventListener('click',()=>openGoal());document.querySelector('#addGoal2')?.addEventListener('click',()=>openGoal());document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openGoal(state.goals.find(g=>g.id===b.dataset.edit)));document.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>{state.goals=state.goals.filter(g=>g.id!==b.dataset.del);persist('Goal deleted');render();});}
function openGoal(item){openModal(`${modalHeader(item?'Edit goal':'Add goal')}<div class="formGrid">${field('Goal name','name','text',item?.name||'','required')}${select('Type','kind',item?.kind||'Savings Goal',['Emergency Fund','Sinking Fund','Savings Goal','Large Purchase','Travel','Education','Other'])}${field('Target amount','target','number',item?.target||'','min="0" step="0.01" required')}${field('Already saved','saved','number',item?.saved||0,'min="0" step="0.01"')}${field('Reserve each paycheck','autoContribution','number',item?.autoContribution||0,'min="0" step="0.01"')}${field('Target date (optional)','deadline','date',item?.deadline||'')}</div>${actions()}`,fd=>{const d={id:item?.id||uid(),name:fd.get('name'),kind:fd.get('kind'),target:Number(fd.get('target')),saved:Number(fd.get('saved')),autoContribution:Number(fd.get('autoContribution')),deadline:fd.get('deadline'),active:true};if(item)Object.assign(item,d);else state.goals.push(d);persist('Goal saved');});}

function investments(){const current=state.investments.reduce((s,i)=>s+Number(i.currentBalance||0),0),future=state.investments.reduce((s,i)=>s+investmentProjection(i),0);layout(`${title('BUILD WEALTH','Investments','Track balances and recurring contributions locally. Projections are planning estimates, not guaranteed returns.',button('Add investment','addInv'))}<section class="stats">${stat('Current investments',money(current,cur()))}${stat('Projected future value',money(future,cur()),'Using your own return assumptions')}</section><section class="cards">${state.investments.length?state.investments.map(i=>`<article class="card"><div class="cardHead"><div><span class="kicker">${esc(i.type||'INVESTMENT')}</span><h2>${esc(i.name)}</h2></div><div class="rowActions"><button data-edit="${i.id}">Edit</button><button data-del="${i.id}">Delete</button></div></div><div class="bigNumber">${money(i.currentBalance,cur())}<small>current balance</small></div><div class="miniStats"><span>Contribution<b>${money(i.contribution,cur())}</b></span><span>Expected return<b>${Number(i.expectedReturn||0).toFixed(1)}%</b></span><span>${Number(i.years||10)}-yr estimate<b>${money(investmentProjection(i),cur())}</b></span></div></article>`).join(''):empty('No investments yet','Add retirement, brokerage, or other investment balances and contributions.',button('Add investment','addInv2'))}</section>`);document.querySelector('#addInv')?.addEventListener('click',()=>openInvestment());document.querySelector('#addInv2')?.addEventListener('click',()=>openInvestment());document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openInvestment(state.investments.find(i=>i.id===b.dataset.edit)));document.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>{state.investments=state.investments.filter(i=>i.id!==b.dataset.del);persist('Investment deleted');render();});}
function openInvestment(item){openModal(`${modalHeader(item?'Edit investment':'Add investment')}<div class="formGrid">${field('Account name','name','text',item?.name||'','required')}${select('Type','type',item?.type||'401(k)',['401(k)','403(b)','TSP','IRA','Roth IRA','Brokerage','529','Pension value','Other'])}${field('Current balance','currentBalance','number',item?.currentBalance||0,'min="0" step="0.01"')}${field('Recurring contribution','contribution','number',item?.contribution||0,'min="0" step="0.01"')}${select('Contribution frequency','frequency',item?.frequency||'biweekly',freqOpts)}${field('Next contribution','startDate','date',item?.startDate||dateString(today()),'required')}${field('Expected annual return %','expectedReturn','number',item?.expectedReturn??7,'min="0" max="100" step="0.1"')}${field('Projection years','years','number',item?.years??10,'min="1" max="60"')}</div>${actions()}`,fd=>{const d={id:item?.id||uid(),name:fd.get('name'),type:fd.get('type'),currentBalance:Number(fd.get('currentBalance')),contribution:Number(fd.get('contribution')),frequency:fd.get('frequency'),startDate:fd.get('startDate'),expectedReturn:Number(fd.get('expectedReturn')),years:Number(fd.get('years')),active:true};if(item)Object.assign(item,d);else state.investments.push(d);persist('Investment saved');});}

function netWorthPage(){const n=netWorth(state),assets=[...state.accounts.filter(a=>a.includeNetWorth!==false).map(a=>({name:a.name,type:a.type,value:Number(a.balance||0)})),...state.investments.map(i=>({name:i.name,type:i.type,value:Number(i.currentBalance||0)}))],debts=state.debts.map(d=>({name:d.name,type:d.type,value:Number(d.balance||0)}));layout(`${title('THE BIG PICTURE','Net Worth','Net worth is simply what you own minus what you owe. Updating balances monthly is enough to make this useful.')}<section class="stats">${stat('Assets',money(n.assets,cur()))}${stat('Liabilities',money(n.liabilities,cur()))}${stat('Net worth',money(n.net,cur()))}</section><section class="grid2"><article class="card"><div class="cardHead"><div><span class="kicker">ASSETS</span><h2>What you own</h2></div></div>${assets.length?assets.sort((a,b)=>b.value-a.value).map(a=>`<div class="row"><div><b>${esc(a.name)}</b><small>${esc(a.type)}</small></div><strong>${money(a.value,cur())}</strong></div>`).join(''):empty('No assets','Add accounts or investments to build your net-worth picture.')}</article><article class="card"><div class="cardHead"><div><span class="kicker">LIABILITIES</span><h2>What you owe</h2></div></div>${debts.length?debts.sort((a,b)=>b.value-a.value).map(d=>`<div class="row"><div><b>${esc(d.name)}</b><small>${esc(d.type)}</small></div><strong class="negative">${money(d.value,cur())}</strong></div>`).join(''):empty('No liabilities','Add debts if you want them included in your net worth.')}</article></section>`);}

function calendar(){const ev=upcomingEvents(state,90),group={};ev.forEach(e=>(group[e.date]??=[]).push(e));layout(`${title('LOOK AHEAD','90-Day Money Calendar','Recurring income, bills, subscriptions, and investments appear automatically.')}<article class="card calendarList">${Object.keys(group).length?Object.entries(group).map(([d,items])=>`<div class="day"><div class="dateBox"><b>${d.slice(8)}</b><span>${new Date(`${d}T00:00:00Z`).toLocaleDateString(undefined,{month:'short',timeZone:'UTC'})}</span></div><div class="dayItems">${items.map(x=>`<div class="calendarItem ${x.type}"><div><b>${esc(x.name)}</b><small>${esc(x.type)}</small></div><strong>${x.type==='income'?'+':'−'}${money(x.amount,cur())}</strong></div>`).join('')}</div></div>`).join(''):empty('Calendar is empty','Add recurring items and the next 90 days will populate automatically.')}</article>`);}

function reports(){const periods=generatePayPeriods(state,12),rows=periods.map(p=>({p,x:periodPlan(state,p)})),budgetRows=budgetStatus(state),subs=state.bills.filter(b=>b.category==='Subscriptions'),monthlySubs=subs.reduce((s,b)=>s+Number(b.amount||0)*(b.frequency==='annual'?1/12:b.frequency==='quarterly'?1/3:b.frequency==='weekly'?52/12:b.frequency==='biweekly'?26/12:1),0),actual=monthlyActuals(state);const cat={};actual.transactions.filter(t=>t.type==='expense').forEach(t=>cat[t.category||'Uncategorized']=(cat[t.category||'Uncategorized']||0)+Number(t.amount||0));const max=Math.max(1,...Object.values(cat));layout(`${title('UNDERSTAND YOUR MONEY','Reports','Simple reports answer where your money goes, what is recurring, and whether your future paychecks stay positive.')}<section class="stats">${stat('Subscriptions / month',money(monthlySubs,cur()),`${money(monthlySubs*12,cur())} estimated annually`)}${stat('Budget categories over limit',String(budgetRows.filter(b=>b.remaining<0).length),'This month')}${stat('Next 12 paychecks negative',String(rows.filter(r=>r.x.available<0).length),'Before discretionary spending')}</section><section class="grid2"><article class="card"><div class="cardHead"><div><span class="kicker">THIS MONTH</span><h2>Spending by category</h2></div></div>${Object.keys(cat).length?Object.entries(cat).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="reportBar"><div><span>${esc(k)}</span><b>${money(v,cur())}</b></div><i><em style="width:${v/max*100}%"></em></i></div>`).join(''):empty('No spending recorded','Add transactions to see category reports.')}</article><article class="card"><div class="cardHead"><div><span class="kicker">FORECAST</span><h2>Next 12 paychecks</h2></div></div>${rows.length?rows.map(r=>`<div class="row"><div><b>${dateString(r.p.payDate)}</b><small>${money(r.x.income,cur())} income · ${money(r.x.bills+r.x.investments+r.x.goals+(r.x.debtPayments||0),cur())} committed</small></div><strong class="${r.x.available<0?'negative':'positive'}">${money(r.x.available,cur())}</strong></div>`).join(''):empty('No forecast','Set a payday to create one.')}</article></section>`);}


function guide(){layout(`${title('PLAIN-LANGUAGE HELP','Money Guide','A built-in reference for the financial concepts OwnLedger uses. No internet connection is required.')}<section class="guideGrid"><article class="card"><span class="kicker">1 · CASH FLOW</span><h2>Give every paycheck a job</h2><p class="muted">Start with required bills, then minimum debt payments, essential spending, savings, and investing. The amount left after those commitments is what is truly available for flexible spending.</p></article><article class="card"><span class="kicker">2 · EMERGENCY FUND</span><h2>Build a buffer before life forces debt</h2><p class="muted">A starter emergency fund can cover smaller surprises. Over time, many households aim for several months of essential expenses. Your right target depends on job stability, insurance, dependents, and risk tolerance.</p></article><article class="card"><span class="kicker">3 · DEBT</span><h2>Understand interest before choosing payoff order</h2><p class="muted">The avalanche method targets the highest APR first and usually minimizes interest. The snowball method targets the smallest balance first and can create faster visible wins. Always keep required minimum payments current.</p></article><article class="card"><span class="kicker">4 · SINKING FUNDS</span><h2>Turn irregular expenses into regular saving</h2><p class="muted">Car repairs, holidays, annual insurance, travel, school costs, and home maintenance are not emergencies when you can reasonably expect them. Saving a small amount each paycheck makes those costs predictable.</p></article><article class="card"><span class="kicker">5 · NET WORTH</span><h2>Track direction, not just one number</h2><p class="muted">Net worth equals assets minus liabilities. A negative number can still improve every month. Update balances periodically and focus on the trend rather than comparing yourself with anyone else.</p></article><article class="card"><span class="kicker">6 · INVESTING</span><h2>Separate projections from promises</h2><p class="muted">OwnLedger's investment estimates use the return assumption you enter. Markets fluctuate and returns are not guaranteed. Use projections to compare saving habits and time horizons, not as a prediction of future value.</p></article><article class="card"><span class="kicker">7 · BUDGETING</span><h2>Control the categories that actually cause problems</h2><p class="muted">You do not need dozens of categories. Start with a few flexible areas such as groceries, dining, shopping, and entertainment. Fixed bills are already handled by the paycheck plan.</p></article><article class="card"><span class="kicker">8 · SECURITY</span><h2>Protect the device and the backups</h2><p class="muted">OwnLedger does not send your data anywhere, but local files still deserve protection. Use full-disk encryption, a strong operating-system password, and encrypted storage for exported backups. Do not enter passwords, PINs, Social Security numbers, or full card numbers into notes or descriptions.</p></article></section><article class="card tip"><b>OwnLedger is an educational planning tool.</b><span>It does not provide individualized financial, tax, legal, or investment advice. For decisions with major tax, legal, insurance, or investment consequences, verify the relevant rules or use an appropriate qualified professional.</span></article>`);}


function paycheckTax(){
  const t=state.taxProfile||{};
  const result=estimatePaycheck({...t,frequency:state.profile.payFrequency||'biweekly'});
  const stateName=US_STATES.find(x=>x[0]===t.state)?.[1]||'Not selected';
  const coverage=t.state==='MD'?'Bundled Maryland planning pack + county/local rates':NO_WAGE_INCOME_TAX_STATES.has(t.state)?'No broad state wage income tax':'Pay-stub effective-rate fallback';
  const calibrated=result.calibration;
  const calibrationText=calibrated?`${money(Math.abs(calibrated.difference),cur())} ${calibrated.difference>=0?'above':'below'} your saved pay-stub net (${(calibrated.percentDifference*100).toFixed(1)}% difference)`:'Add the take-home amount from a real pay stub to compare the estimate.';
  layout(`${title('PAYROLL-LEVEL PLANNING','Paycheck & Tax Estimate','2026 federal withholding follows the IRS Publication 15-T automated percentage method. State/local accuracy depends on the bundled jurisdiction pack or the pay-stub rate you provide.',button('Edit paycheck & W-4','editTax'))}
  <article class="card tip"><b>Better than a salary calculator, still not your employer's payroll system.</b><span>OwnLedger models W-4 Steps 2, 3, and 4, FICA wage-base rules, year-to-date wages, deductions, and local taxes. Employer benefit coding and jurisdiction-specific payroll rules can still create differences, so you can calibrate against a real pay stub.</span></article>
  <section class="stats">${stat('Gross pay',money(result.gross,cur()),state.profile.payFrequency)}${stat('Estimated taxes',money(result.taxes,cur()),`${(result.effectiveTaxRate*100).toFixed(1)}% of gross`)}${stat('Other deductions',money(result.preTax+result.postTax,cur()),'Federal pre-tax + post-tax')}${stat('Estimated take-home',money(result.takeHome,cur()),'Feeds the budget')}</section>
  <section class="grid2"><article class="card"><div class="cardHead"><div><span class="kicker">PAYCHECK BREAKDOWN</span><h2>Where gross pay goes</h2></div></div>
    <div class="moneyFlow"><div><span>Gross pay</span><b>${money(result.gross,cur())}</b></div><div><span>Pre-tax federal deductions</span><b>− ${money(result.preTax,cur())}</b></div><div><span>Federal withholding</span><b>− ${money(result.federalPerPay,cur())}</b></div><div><span>Social Security</span><b>− ${money(result.socialPerPay,cur())}</b></div><div><span>Medicare</span><b>− ${money(result.medicarePerPay,cur())}</b></div><div><span>${esc(stateName)} income tax</span><b>− ${money(result.statePerPay,cur())}</b></div><div><span>${t.county?esc(t.county):'Local income tax'}</span><b>− ${money(result.localPerPay,cur())}</b></div><div><span>Post-tax deductions</span><b>− ${money(result.postTax,cur())}</b></div><div class="total"><span>Estimated take-home</span><b>${money(result.takeHome,cur())}</b></div></div>
  </article><article class="card"><div class="cardHead"><div><span class="kicker">2026 WITHHOLDING MODEL</span><h2>What OwnLedger is using</h2></div></div>
    <div class="row"><div><b>Federal method</b><small>IRS Publication 15-T automated percentage method</small></div><strong>2026</strong></div><div class="row"><div><b>W-4 Step 2</b><small>Multiple-jobs / spouse-works checkbox</small></div><strong>${t.w4Step2Checked?'Checked':'Not checked'}</strong></div><div class="row"><div><b>Filing status</b></div><strong>${esc((t.filingStatus||'single').replaceAll('_',' '))}</strong></div><div class="row"><div><b>State/local coverage</b><small>${esc(coverage)}</small></div></div>
    <div class="row"><div><b>Pay-stub calibration</b><small>${esc(calibrationText)}</small></div></div>
    <button class="button primary" type="button" id="useTakeHome">Use ${money(result.takeHome,cur())} as primary paycheck</button>
    ${calibrated?`<button class="button ghost" type="button" id="useActual">Use actual pay-stub net ${money(calibrated.actualTakeHome,cur())}</button>`:''}
  </article></section>
  <article class="card"><div class="cardHead"><div><span class="kicker">W-4 TRACE</span><h2>Federal withholding calculation</h2></div></div><div class="miniStats"><span>Taxable wages this check<b>${money(result.federalDetails.taxableWages,cur())}</b></span><span>Adjusted annual wage<b>${money(result.federalDetails.adjustedAnnual,cur())}</b></span><span>Tentative annual withholding<b>${money(result.federalDetails.tentativeAnnual,cur())}</b></span></div><p class="muted">This trace makes the estimate auditable instead of hiding the assumptions. The tax tables are bundled with OwnLedger; nothing is looked up online while the app is running.</p></article>`);
  document.querySelector('#editTax').onclick=openTaxProfile;
  document.querySelector('#useTakeHome').onclick=()=>usePrimaryPaycheck(result.takeHome,'Estimated take-home pay updated');
  document.querySelector('#useActual')?.addEventListener('click',()=>usePrimaryPaycheck(calibrated.actualTakeHome,'Actual pay-stub take-home used'));
}

function usePrimaryPaycheck(amount,message){
  const primary=primaryIncome();
  if(!primary){state.income.push({id:uid(),name:'Primary paycheck',amount,frequency:state.profile.payFrequency,startDate:state.profile.nextPayDate||dateString(today()),category:'Paycheck',active:true,isPrimaryPaycheck:true});}
  else{primary.amount=amount;primary.frequency=state.profile.payFrequency;primary.startDate=state.profile.nextPayDate||primary.startDate||dateString(today());primary.isPrimaryPaycheck=true;}
  persist(message);render();
}

function openTaxProfile(){
  const t=state.taxProfile||{};
  const countyOptions=[['','Select county / city'],...Object.keys(MD_LOCAL_2026).map(x=>[x,x])];
  openModal(`${modalHeader('Paycheck, W-4 & tax profile','Use the same values that appear on your pay stub and W-4. Do not enter an SSN, account number, PIN, or password.')}
    <div class="formGrid">${field('Gross pay per paycheck','grossPay','number',t.grossPay||'','min="0" step="0.01" required')}${select('Pay frequency','frequency',state.profile.payFrequency,[['weekly','Weekly'],['biweekly','Every 2 weeks'],['semimonthly','Twice monthly'],['monthly','Monthly']])}${select('Federal filing status (W-4 Step 1)','filingStatus',t.filingStatus||'single',[['single','Single / married filing separately'],['married_joint','Married filing jointly'],['head_household','Head of household']])}${select('State of residence','state',t.state||'',[['','Select a state'],...US_STATES])}${select('Maryland county / Baltimore City','county',t.county||'',countyOptions)}
    ${field('Pre-tax deductions taken from this paycheck','preTaxFederalDeductions','number',t.preTaxFederalDeductions||0,'min="0" step="0.01"')}${field('Of those pre-tax deductions, amount also exempt from Social Security/Medicare','preTaxFicaDeductions','number',t.preTaxFicaDeductions||0,'min="0" step="0.01"')}${field('Post-tax deductions per paycheck','postTaxDeductions','number',t.postTaxDeductions||0,'min="0" step="0.01"')}
    ${checkbox('W-4 Step 2 checkbox is checked (multiple jobs / spouse works)','w4Step2Checked',Boolean(t.w4Step2Checked))}${field('W-4 Step 4(a): other annual income','w4OtherIncome','number',t.w4OtherIncome||0,'min="0" step="0.01"')}${field('W-4 Step 4(b): annual deductions','w4Deductions','number',t.w4Deductions||0,'min="0" step="0.01"')}${field('W-4 Step 3: annual credits','w4Credits','number',t.w4Credits||0,'min="0" step="0.01"')}${field('W-4 Step 4(c): extra withholding / paycheck','w4AdditionalWithholding','number',t.w4AdditionalWithholding||0,'min="0" step="0.01"')}
    ${field('Social Security wages YTD before this paycheck','socialSecurityWagesYTD','number',t.socialSecurityWagesYTD||0,'min="0" step="0.01"')}${field('Medicare wages YTD before this paycheck','medicareWagesYTD','number',t.medicareWagesYTD||0,'min="0" step="0.01"')}${field('Actual take-home from a recent pay stub (optional)','paystubActualTakeHome','number',t.paystubActualTakeHome||0,'min="0" step="0.01"')}
    ${field('State annual deduction / adjustment','stateAnnualDeduction','number',t.stateAnnualDeduction||0,'min="0" step="0.01"')}${field('State effective withholding rate % (fallback)','stateEffectiveRate','number',t.stateEffectiveRate||0,'min="0" max="20" step="0.01"')}${field('Local effective withholding rate % (fallback)','localEffectiveRate','number',t.localEffectiveRate||0,'min="0" max="10" step="0.01"')}</div>
    <div class="modalNote">Enter the FICA-exempt amount as a subset of the total pre-tax deductions above—do not add the same deduction twice. Federal withholding uses the bundled 2026 IRS Publication 15-T automated percentage tables. Maryland state/local values remain planning estimates; unsupported jurisdictions use the effective withholding rate you copy from a real pay stub until a verified offline pack is included.</div>${actions('Save paycheck profile')}`,fd=>{
      state.profile.payFrequency=fd.get('frequency');
      state.taxProfile={...state.taxProfile,grossPay:Number(fd.get('grossPay')),filingStatus:fd.get('filingStatus'),state:fd.get('state'),county:fd.get('county'),preTaxFederalDeductions:Number(fd.get('preTaxFederalDeductions')),preTaxFicaDeductions:Number(fd.get('preTaxFicaDeductions')),postTaxDeductions:Number(fd.get('postTaxDeductions')),w4Step2Checked:fd.has('w4Step2Checked'),w4OtherIncome:Number(fd.get('w4OtherIncome')),w4Deductions:Number(fd.get('w4Deductions')),w4Credits:Number(fd.get('w4Credits')),w4AdditionalWithholding:Number(fd.get('w4AdditionalWithholding')),socialSecurityWagesYTD:Number(fd.get('socialSecurityWagesYTD')),medicareWagesYTD:Number(fd.get('medicareWagesYTD')),paystubActualTakeHome:Number(fd.get('paystubActualTakeHome')),stateAnnualDeduction:Number(fd.get('stateAnnualDeduction')),stateEffectiveRate:Number(fd.get('stateEffectiveRate')),localEffectiveRate:Number(fd.get('localEffectiveRate')),taxYear:TAX_YEAR};persist('Paycheck profile saved');
    });
}

function affordability(){
  const saved=state.purchasePlans||[];
  layout(`${title('BEFORE YOU BUY','Affordability Planner','Ask OwnLedger whether a purchase fits your finances now, whether saving first is better, and what financing would do to your monthly obligations.',button('Plan a purchase','newPurchase'))}
    <article class="card tip"><b>This planner does not decide what you are allowed to buy.</b><span>It compares the purchase with the financial priorities you entered—cash reserves, income, recurring obligations, debt, budgets, and goals—then shows the tradeoffs.</span></article>
    <section class="cards">${saved.length?saved.map(p=>purchaseCard(p)).join(''):empty('No purchase plans yet','Try a couch, car repair, computer, vacation, appliance, or any other planned purchase.',button('Plan my first purchase','newPurchase2'))}</section>`);
  document.querySelector('#newPurchase')?.addEventListener('click',()=>openPurchase());document.querySelector('#newPurchase2')?.addEventListener('click',()=>openPurchase());
  document.querySelectorAll('[data-edit-purchase]').forEach(b=>b.onclick=()=>openPurchase(saved.find(x=>x.id===b.dataset.editPurchase)));
  document.querySelectorAll('[data-del-purchase]').forEach(b=>b.onclick=()=>{if(confirm('Delete this purchase plan?')){state.purchasePlans=state.purchasePlans.filter(x=>x.id!==b.dataset.delPurchase);persist('Purchase plan deleted');render();}});
}
function purchaseCard(p){
  const x=affordabilityPlan(state,p);const badge=x.recommendation==='cash'?'Cash looks viable':x.recommendation==='finance'?'Financing may fit':x.recommendation==='save'?'Save first':'Wait';
  const timeline=Number.isFinite(x.saveMonths)?(x.saveMonths===0?'Affordable from cash above reserve':`${x.saveMonths} month${x.saveMonths===1?'':'s'} to save`):'No savings timeline with current cash flow';
  return `<article class="card purchase"><div class="cardHead"><div><span class="kicker">${esc(badge.toUpperCase())}</span><h2>${esc(p.name)}</h2></div><div class="rowActions"><button data-edit-purchase="${p.id}">Edit</button><button data-del-purchase="${p.id}">Delete</button></div></div><div class="goalBig"><strong>${money(p.price,cur())}</strong><span>purchase price</span></div><p class="muted">${esc(x.reason)}</p><div class="miniStats"><span>Free cash flow <b>${money(x.free,cur())}/mo</b></span><span>Save timeline <b>${esc(timeline)}</b></span><span>Finance payment <b>${money(x.payment,cur())}/mo</b></span></div><div class="purchaseCompare"><div><b>Cash</b><span>Cash above emergency target: ${money(x.safeCash,cur())}</span></div><div><b>Save</b><span>${Number.isFinite(x.saveMonths)?`${x.saveMonths} months estimated`:'Not currently feasible'}</span></div><div><b>Finance</b><span>${money(x.totalFinancedCost,cur())} total · ${money(x.interestCost,cur())} interest</span></div></div><small class="muted">Estimated debt-payment ratio after financing: ${(x.dtiAfter*100).toFixed(1)}% of net monthly income.</small></article>`;
}
function openPurchase(item){openModal(`${modalHeader(item?'Edit purchase plan':'Plan a purchase','Enter only the purchase terms. OwnLedger uses the budget, debt, cash, and income information you already entered.')}
  <div class="formGrid">${field('What do you want to buy?','name','text',item?.name||'','required')}${field('Purchase price','price','number',item?.price||'','min="0" step="0.01" required')}${field('Possible down payment','downPayment','number',item?.downPayment||0,'min="0" step="0.01"')}${field('Financing APR %','apr','number',item?.apr||0,'min="0" max="100" step="0.01"')}${field('Financing term (months)','termMonths','number',item?.termMonths||12,'min="1" max="120"')}</div>${actions('Analyze purchase')}`,fd=>{const data={id:item?.id||uid(),name:fd.get('name'),price:Number(fd.get('price')),downPayment:Number(fd.get('downPayment')),apr:Number(fd.get('apr')),termMonths:Number(fd.get('termMonths')),createdAt:item?.createdAt||new Date().toISOString()};if(item)Object.assign(item,data);else state.purchasePlans.push(data);persist('Purchase plan saved');});}


function decisionCenter(){
  const snap=financialSnapshot(state), history=[...(state.decisionScenarios||[])].sort((a,b)=>(b.createdAt||'').localeCompare(a.createdAt||''));
  const choices=[
    ['purchase','Can I afford a purchase?','Compare cash, saving, and financing using your existing budget.'],
    ['vehicle','Can I afford this vehicle?','Include payment, insurance, fuel, maintenance, reserves, and monthly breathing room.'],
    ['housing','Can I afford this housing?','Evaluate rent or home ownership against net income and reserves.'],
    ['income','What if my income changes?','See how a raise, new job, reduced hours, or other take-home change affects the plan.'],
    ['overtime','How much overtime do I need?','Translate a savings target and deadline into estimated overtime hours.'],
    ['bonus','What should I do with a bonus?','Prioritize emergency savings, high-interest debt, goals, then long-term saving.'],
    ['refinance','Should I refinance?','Compare current debt terms with a proposed refinance including fees.'],
    ['whatif','What if I change my budget?','Stress-test income, bills, debt, investing, and savings changes together.']
  ];
  layout(`${title('MAKE THE NEXT MOVE','Decision Center','Use the financial information already stored on this device to answer real-life money questions. Results are planning guidance, not lending, tax, or investment advice.')}
    <section class="stats">${stat('Monthly take-home',money(snap.income,cur()))}${stat('Monthly free cash',money(snap.free,cur()),'After commitments and category budgets')}${stat('Cash above reserve',money(snap.safeCash,cur()))}${stat('Debt balance',money(snap.debtBalance,cur()))}</section>
    <section class="decisionGrid">${choices.map(([id,h,p])=>`<button type="button" class="decisionChoice" data-decision="${id}"><span class="decisionIcon">◆</span><div><b>${esc(h)}</b><small>${esc(p)}</small></div><span>→</span></button>`).join('')}</section>
    <article class="card"><div class="cardHead"><div><span class="kicker">RECENT ANALYSES</span><h2>Your decision history</h2></div>${history.length?'<button type="button" class="button ghost small" id="clearDecisions">Clear history</button>':''}</div>
    ${history.length?`<div class="decisionHistory">${history.slice(0,12).map(renderDecisionHistory).join('')}</div>`:empty('No decisions analyzed yet','Choose a question above. OwnLedger will save the result locally so you can compare it later.')}</article>`);
  document.querySelectorAll('[data-decision]').forEach(b=>b.onclick=()=>openDecision(b.dataset.decision));
  document.querySelector('#clearDecisions')?.addEventListener('click',()=>{if(confirm('Clear saved Decision Center history?')){state.decisionScenarios=[];persist('Decision history cleared');render();}});
}

function decisionTone(result){
  const x=String(result?.recommendation||result?.impact||result?.status||'').toLowerCase();
  if(x.includes('comfortable')||x.includes('refinance may')||x==='positive'||x==='improves')return'positive';
  if(x.includes('tight')||x.includes('manageable'))return'warning';
  if(x.includes('wait')||x.includes('shortfall')||x.includes('keep current'))return'negative';
  return'';
}
function renderDecisionHistory(d){
  const r=d.result||{}, summary=d.summary||r.reason||'';
  return `<div class="decisionResult ${decisionTone(r)}"><div><span class="kicker">${esc((d.type||'decision').replaceAll('-',' ').toUpperCase())}</span><b>${esc(d.title||'Decision analysis')}</b><small>${esc(summary)}</small></div><span>${new Date(d.createdAt||Date.now()).toLocaleDateString()}</span></div>`;
}
function saveDecision(type,title,input,result,summary){
  state.decisionScenarios=state.decisionScenarios||[];
  state.decisionScenarios.push({id:uid(),type,title,input,result,summary,createdAt:new Date().toISOString()});
  persist('Decision analysis saved');
}
function decisionResultModal(title,resultHtml,onSave){
  const d=document.querySelector('#modal');
  document.querySelector('#modalBody').innerHTML=`${modalHeader(title)}<div class="decisionModalResult">${resultHtml}</div><div class="modalActions"><button type="button" class="button ghost" data-close>Close</button><button type="button" class="button primary" id="saveDecisionResult">Save analysis</button></div>`;
  document.querySelectorAll('[data-close]').forEach(x=>x.onclick=()=>d.close());
  document.querySelector('#saveDecisionResult').onclick=()=>{onSave();d.close();render();};
  if(!d.open)d.showModal();
}
function recommendationCard(label,reason,metrics=''){
  return `<div class="recommendation"><span class="kicker">OWNLEDGER GUIDANCE</span><h2>${esc(label)}</h2><p>${esc(reason)}</p>${metrics?`<div class="decisionMetrics">${metrics}</div>`:''}</div>`;
}
function metric(label,value){return `<div><span>${esc(label)}</span><b>${value}</b></div>`;}

function openDecision(type){
  if(type==='purchase'){location.hash='#/affordability';return;}
  if(type==='vehicle') return openModal(`${modalHeader('Vehicle affordability','Use realistic ownership costs—not just the loan payment.')}<div class="formGrid">${field('Vehicle price','price','number','','min="0" step="0.01" required')}${field('Down payment','downPayment','number',0,'min="0" step="0.01"')}${field('Trade-in value','tradeIn','number',0,'min="0" step="0.01"')}${field('APR %','apr','number',7,'min="0" step="0.01"')}${field('Loan term months','termMonths','number',60,'min="1" max="120"')}${field('Insurance / month','insuranceMonthly','number',150,'min="0" step="0.01"')}${field('Fuel / month','fuelMonthly','number',150,'min="0" step="0.01"')}${field('Maintenance reserve / month','maintenanceMonthly','number',75,'min="0" step="0.01"')}</div>${actions('Analyze vehicle')}`,fd=>{const input=Object.fromEntries(fd);const r=vehicleDecision(state,input);setTimeout(()=>decisionResultModal('Vehicle decision',recommendationCard(r.recommendation,r.reason,metric('Loan payment',money(r.payment,cur()))+metric('All-in monthly cost',money(r.ownershipMonthly,cur()))+metric('Monthly cash left',money(r.freeAfter,cur()))+metric('Total loan interest',money(r.totalInterest,cur()))),()=>saveDecision('vehicle','Vehicle affordability',input,r,r.reason)),0);});
  if(type==='housing') return openModal(`${modalHeader('Housing affordability','Choose rent or home purchase. OwnLedger evaluates the monthly cost against take-home income.')}<div class="formGrid">${select('Housing type','mode','rent',[['rent','Rent'],['buy','Buy a home']])}${field('Monthly rent (if renting)','rent','number',0,'min="0" step="0.01"')}${field('Home price (if buying)','homePrice','number',0,'min="0" step="0.01"')}${field('Down payment','downPayment','number',0,'min="0" step="0.01"')}${field('Mortgage APR %','apr','number',6.5,'min="0" step="0.01"')}${field('Mortgage term years','termYears','number',30,'min="1" max="40"')}${field('Property tax / year','propertyTaxAnnual','number',0,'min="0" step="0.01"')}${field('Home insurance / year','insuranceAnnual','number',0,'min="0" step="0.01"')}${field('HOA / month','hoaMonthly','number',0,'min="0" step="0.01"')}${field('Utilities / month','utilities','number',0,'min="0" step="0.01"')}${field('Renters insurance / month','insuranceMonthly','number',0,'min="0" step="0.01"')}</div>${actions('Analyze housing')}`,fd=>{const input=Object.fromEntries(fd);const r=housingDecision(state,input);setTimeout(()=>decisionResultModal('Housing decision',recommendationCard(r.recommendation,r.reason,metric('Estimated housing / month',money(r.housing,cur()))+metric('Share of net income',`${(r.ratio*100).toFixed(1)}%`)+metric('Monthly cash left',money(r.freeAfter,cur()))+(r.mode==='buy'?metric('Cash after down payment',money(r.reserveAfter,cur())):'')),()=>saveDecision('housing','Housing affordability',input,r,r.reason)),0);});
  if(type==='income') return openModal(`${modalHeader('Income change','Enter the expected new monthly take-home amount. Use Paycheck & Taxes first if you only know gross salary.')}<div class="formGrid">${field('New monthly take-home','newMonthlyNet','number','','min="0" step="0.01" required')}</div>${actions('Analyze income change')}`,fd=>{const input=Object.fromEntries(fd),r=incomeChangeDecision(state,input);setTimeout(()=>decisionResultModal('Income-change decision',recommendationCard(r.impact,r.reason,metric('Current monthly net',money(r.snap.income,cur()))+metric('New monthly net',money(r.newMonthlyNet,cur()))+metric('Monthly change',money(r.delta,cur()))+metric('New free cash',money(r.newFree,cur()))),()=>saveDecision('income-change','Income change',input,r,r.reason)),0);});
  if(type==='overtime') return openModal(`${modalHeader('Overtime needed','Use your estimated take-home earnings per overtime hour, not gross hourly pay.')}<div class="formGrid">${field('Amount you want to fund','targetAmount','number','','min="0" step="0.01" required')}${field('Deadline in months','months','number',6,'min="1" max="120" required')}${field('Take-home per overtime hour','netHourly','number','','min="0.01" step="0.01" required')}</div>${actions('Calculate overtime')}`,fd=>{const input=Object.fromEntries(fd),r=overtimeDecision(state,input);const summary=r.feasible?`About ${r.hoursPerWeek.toFixed(1)} overtime hours per week would cover the remaining target after applying current free cash flow.`:'Enter a positive take-home amount per overtime hour.';setTimeout(()=>decisionResultModal('Overtime plan',recommendationCard('overtime plan',summary,metric('Existing cash-flow contribution',money(r.existingContribution,cur()))+metric('Still needed',money(r.remaining,cur()))+metric('Hours / month',Number.isFinite(r.hoursPerMonth)?r.hoursPerMonth.toFixed(1):'—')+metric('Hours / week',Number.isFinite(r.hoursPerWeek)?r.hoursPerWeek.toFixed(1):'—')),()=>saveDecision('overtime','Overtime requirement',input,r,summary)),0);});
  if(type==='bonus') return openModal(`${modalHeader('Bonus allocation','Enter the after-tax amount that will actually reach you.')}<div class="formGrid">${field('Net bonus amount','bonusNet','number','','min="0" step="0.01" required')}</div>${actions('Build bonus plan')}`,fd=>{const input=Object.fromEntries(fd),r=bonusAllocationDecision(state,input);const rows=r.allocations.map(a=>`<div class="allocationRow"><div><b>${esc(a.bucket)}</b><small>${esc(a.reason)}</small></div><strong>${money(a.amount,cur())}</strong></div>`).join('')||'<p class="muted">Enter a positive bonus amount.</p>';setTimeout(()=>decisionResultModal('Bonus allocation',`<div class="recommendation"><span class="kicker">SUGGESTED ORDER</span><h2>Put the money where it has the most leverage</h2><div class="allocationList">${rows}</div></div>`,()=>saveDecision('bonus','Bonus allocation',input,r,'Prioritized emergency reserves, high-interest debt, active goals, then long-term savings.')),0);});
  if(type==='refinance') return openModal(`${modalHeader('Refinance comparison','Compare remaining current debt cost with a proposed refinance.')}<div class="formGrid">${field('Balance to refinance','balance','number','','min="0" step="0.01" required')}${field('Current APR %','currentApr','number','','min="0" step="0.01" required')}${field('Current months remaining','currentMonths','number','','min="1" required')}${field('New APR %','newApr','number','','min="0" step="0.01" required')}${field('New term months','newMonths','number','','min="1" required')}${field('Refinance fees','fees','number',0,'min="0" step="0.01"')}</div>${actions('Compare refinance')}`,fd=>{const input=Object.fromEntries(fd),r=refinanceDecision(input);setTimeout(()=>decisionResultModal('Refinance decision',recommendationCard(r.recommendation,r.reason,metric('Current payment',money(r.currentPayment,cur()))+metric('New payment',money(r.newPayment,cur()))+metric('Estimated total savings',money(r.savings,cur()))+metric('Fee break-even',Number.isFinite(r.breakEven)?`${r.breakEven.toFixed(1)} months`:'No break-even')),()=>saveDecision('refinance','Refinance comparison',input,r,r.reason)),0);});
  if(type==='whatif') return openModal(`${modalHeader('What-if scenario','Use positive numbers for increases and negative numbers for decreases.')}<div class="formGrid">${field('Monthly take-home change','incomeDelta','number',0,'step="0.01"')}${field('Monthly bills change','billDelta','number',0,'step="0.01"')}${field('Monthly debt payment change','debtDelta','number',0,'step="0.01"')}${field('Monthly investing change','investDelta','number',0,'step="0.01"')}${field('Monthly savings-goal change','goalDelta','number',0,'step="0.01"')}</div>${actions('Run scenario')}`,fd=>{const input=Object.fromEntries(fd),r=whatIfDecision(state,input);const summary=r.newFree>=0?`The changed plan leaves ${money(r.newFree,cur())} per month uncommitted.`:`The changed plan creates a ${money(Math.abs(r.newFree),cur())} monthly shortfall.`;setTimeout(()=>decisionResultModal('What-if result',recommendationCard(r.status,summary,metric('Current free cash',money(r.currentFree,cur()))+metric('New free cash',money(r.newFree,cur()))+metric('Monthly change',money(r.monthlyChange,cur()))),()=>saveDecision('what-if','Budget what-if',input,r,summary)),0);});
}


function settings(){layout(`${title('CONTROL & SAFETY','Settings & Backup','OwnLedger is designed so the desktop application never needs the internet.')}<section class="grid2"><article class="card"><div class="cardHead"><div><span class="kicker">BASICS</span><h2>Preferences</h2></div></div><form id="settingsForm" class="stack">${field('Name','name','text',state.profile.name)}${select('Currency','currency',state.profile.currency,[['USD','USD — US Dollar'],['CAD','CAD — Canadian Dollar'],['EUR','EUR — Euro'],['GBP','GBP — British Pound'],['AUD','AUD — Australian Dollar'],['JPY','JPY — Japanese Yen']])}${field('Emergency fund target','emergency','number',state.profile.emergencyFundTarget,'min="0" step="0.01"')}${field('Backup reminder (days)','backupReminderDays','number',state.settings.backupReminderDays||30,'min="1" max="365" step="1"')}${checkbox('Include investment contributions in paycheck plans','inv',state.settings.includeInvestmentsInPlan)}${checkbox('Include goal contributions in paycheck plans','goals',state.settings.includeGoalsInPlan)}<button class="button primary" type="submit">Save preferences</button></form></article><article class="card"><div class="cardHead"><div><span class="kicker">OFFLINE BACKUP</span><h2>Protect your data</h2></div></div><p class="muted">Because there is no cloud account, your device is the primary copy. Export a backup to an encrypted drive or other storage you control.</p><div class="stack actionsFull"><button class="button ghost" id="export">Export OwnLedger backup</button><label class="button ghost fileBtn">Restore from backup<input id="import" type="file" accept="application/json,.json"></label><button class="button danger" id="reset">Erase all local data</button></div><small class="muted">Last backup: ${state.meta.lastBackupAt?new Date(state.meta.lastBackupAt).toLocaleString():'No backup recorded yet'}</small></article></section><section class="grid2"><article class="card"><span class="kicker">NETWORK SAFETY</span><h2>The desktop build has a network kill-switch</h2><p class="muted">The Electron shell blocks network requests at runtime, blocks external navigation and popups, exposes no Node.js APIs to the finance UI, and uses a Content Security Policy with <code>connect-src 'none'</code>. There are no analytics, bank integrations, ads, or automatic update checks.</p></article><article class="card"><span class="kicker">OWNLEDGER 1.0.0</span><h2>Email signup stays outside the app</h2><p class="muted">To preserve the offline security promise, OwnLedger itself does not collect an email address or contact an update service. Users can optionally join an update mailing list on the website where they downloaded the application. That list is operationally separate from their financial data.</p></article></section>`);document.querySelector('#settingsForm').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.currentTarget);state.profile.name=fd.get('name');state.profile.currency=fd.get('currency');state.profile.emergencyFundTarget=Number(fd.get('emergency'));state.settings.backupReminderDays=Math.max(1,Math.min(365,Number(fd.get('backupReminderDays')||30)));state.settings.includeInvestmentsInPlan=fd.has('inv');state.settings.includeGoalsInPlan=fd.has('goals');persist('Settings saved');render();};document.querySelector('#export').onclick=()=>{state.meta.lastBackupAt=exportBackup(state);persist('Backup exported');render();};document.querySelector('#import').onchange=async e=>{try{state=await importBackup(e.target.files[0]);toast('Backup restored');render();}catch(err){alert(err.message);}};document.querySelector('#reset').onclick=()=>{if(confirm('Erase ALL OwnLedger data stored on this device? This cannot be undone without a backup.')){resetState();state=loadState();render();}};}

function render(){state=loadState();const r=route();({dashboard, 'action-center':actionCenter,'decision-center':decisionCenter,'paycheck-tax':paycheckTax,'pay-periods':payPeriods,budget, income:()=>recurringPage('income'),bills:()=>recurringPage('bills'),affordability,accounts,transactions,debts,goals,investments,'net-worth':netWorthPage,calendar,reports,guide,settings}[r]||dashboard)();}
window.addEventListener('hashchange',render);render();
